L=['QUIZ DI FINE ARGOMENTO · PSICOLOGIA (Prof. Giorgio Mazzotti) · proposta della chat di produzione, DA APPROVARE','Solo contenuti della slide e del parlato del docente. La risposta giusta è segnata con ✓.','']
for k,v in Q.items():
    L.append(v['title'])
